<script>
import {fixtureSteps} from './fixture-steps.mjs';
import {onMount} from 'svelte';import {api} from './api.js';import FollowingLog from './FollowingLog.svelte';export let data;
let profiles=data.profiles,profileId=data.profileId || profiles[0]?.id,sets=data.fixtures,job=data.job?.command==='fixtures'?data.job:null,busyJob=data.job,pending=false,error='',events;
$: steps=fixtureSteps(job);
$: profile=profiles.find(p=>p.id===profileId);
$: active=['starting','running','pausing','paused','cancelling'].includes(busyJob?.status) && busyJob?.command!=='reconcile';
async function start(){pending=true;error='';try{job=await api.start('fixtures',{mode:profile.mode,profileId:profile.id,version:profile.version});busyJob=job;sets=await api.fixtures();watch();}catch(e){error=e.message;}finally{pending=false;}}
function watch(){events?.close();events=new EventSource(`/api/jobs/${job.id}/events`);events.addEventListener('progress',async event=>{job=JSON.parse(event.data);busyJob=job;if(!['starting','running','cancelling'].includes(job.status)){events.close();sets=await api.fixtures();if(job.error)error=job.error;}});}
async function stop(){try{job=await api.cancel(job.id);busyJob=job;}catch(e){error=e.message;}}
onMount(()=>{const connections=async()=>{try{sets=await api.fixtures();error='';}catch(e){error=e.message;}};window.addEventListener('console-connections-saved',connections);if(job&&active)watch();const poll=setInterval(async()=>{try{const r=await fetch('/api/jobs');if(r.ok)busyJob=await r.json();}catch{}},3000);return()=>{events?.close();clearInterval(poll);window.removeEventListener('console-connections-saved',connections);};});
</script>
<svelte:head><title>Fixtures · Hyperswitch</title></svelte:head>
<main><div class="section-head"><div><h1>Fixtures</h1><p>Merchant accounts, profiles, API keys, MCAs and runtime defaults</p></div><button class="secondary" onclick={()=>window.dispatchEvent(new Event('console-settings'))}>Connection settings</button></div>{#if error}<div class="message error" role="alert">{error}</div>{/if}
<div class="load-controls"><label>Scenario<select bind:value={profileId}>{#each profiles as p}<option value={p.id}>{p.name} · {p.mode==='tenancy'?'Tenancy':'Single'} · v{p.version}</option>{/each}</select></label><div class="fixture-summary"><strong>{profile?.mode==='tenancy'?'Tenancy':'Single'} · {profile?.merchantCount} {profile?.merchantCount===1?'merchant':'merchants'}</strong><p>Provisioning uses the connections and Superposition defaults in Settings.</p></div></div><div class="actions"><button disabled={pending||active||!profile} onclick={start}>{pending?'Starting…':active?'Job in progress':'Create / recover fixtures'}</button></div>
{#if job}<section class="activity"><div class="section-head"><h2>Fixture setup · {job.status}</h2>{#if active}<button class="secondary" onclick={stop}>Stop</button>{/if}</div><p role="status">{job.progress?.fixtures?.completed ?? 0} / {job.progress?.fixtures?.total ?? profile?.merchantCount} merchants provisioned</p><progress aria-label="Fixture provisioning progress" value={job.status==='complete'?(job.progress?.fixtures?.total ?? profile?.merchantCount):(job.progress?.fixtures?.completed ?? 0)} max={job.progress?.fixtures?.total ?? profile?.merchantCount}></progress><div class="setup-steps" aria-label="Fixture setup steps">{#each steps as step}<div class="setup-step" class:running={step.status==='running'} class:complete={step.status==='complete'}><div><strong>{step.label}</strong><span>{step.status==='running'?'In progress':step.status==='complete'?'Complete':step.status==='failed'?'Stopped':step.status==='skipped'?'Skipped':'Pending'}</span></div>{#if step.detail}<p role="status">{step.detail}</p>{/if}{#if step.label==='Service refresh'&&step.status==='running'&&step.total>0}<progress aria-label="Superposition service refresh progress" value={step.total-step.remaining} max={step.total}></progress>{/if}</div>{/each}</div><ol>{#each job.events || [] as event}<li><time>{new Date(event.at).toLocaleTimeString()}</time><span>{event.message}</span></li>{/each}</ol><details class="diagnostics"><summary>Provisioning output</summary><FollowingLog output={job.output || ''} label="Provisioning output"/></details></section>{/if}
<div class="section-head panels-head"><h2>Fixture sets</h2></div><div class="table-wrap"><table><thead><tr><th>Set</th><th>Mode</th><th>Merchants</th><th>Status</th><th></th></tr></thead><tbody>{#each sets as set}<tr><td>{set.id.slice(0,8)}</td><td>{set.mode==='tenancy'?'Tenancy':'Single'}</td><td>{set.merchant_count}</td><td>{set.status}{set.status==='ready'&&!set.compatible?' · settings changed':''}</td><td>{#if set.status==='ready'&&set.compatible&&set.mode===profile?.mode&&set.merchant_count===profile?.merchantCount}<a class="button secondary" href={`/performance?profile=${profileId}&fixtures=${set.id}`}>Use in Performance →</a>{/if}</td></tr>{/each}</tbody></table></div></main>

<style>.setup-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 24px}.setup-step{padding:14px;border:1px solid var(--border);border-radius:8px;background:#fafbfc}.setup-step.running{border-color:#0561e2;background:#f4f8ff}.setup-step>div{display:flex;flex-direction:column;gap:8px}.setup-step strong{font-size:12px}.setup-step span,.setup-step p{font-size:11px;color:#667085}.setup-step p{margin:10px 0 0}.setup-step.complete span{color:#027a48}.setup-step progress{margin:10px 0 0}@media(max-width:800px){.setup-steps{grid-template-columns:1fr 1fr}}@media(max-width:450px){.setup-steps{grid-template-columns:1fr}}</style>
